mapper.select:
    		select pos_num sessionendNum,pos.asset_code assetcode,ca.ASSET_TYPE assettype,ca.ASSET_TYPE2 assettype2 from
			CHB_BOT_AST_POS pos
			left join CHB_ASSET_INFO ca on ca.ASSET_CODE=pos.ASSET_CODE
			and CA.STATUS !='D'
			where PLAN_ASSET_ID=#{assetcode, jdbcType = VARCHAR}
			and pos_date=(select max(pos_date) from CHB_BOT_AST_POS
			where PLAN_ASSET_ID=#{assetcode, jdbcType = VARCHAR} 
			and pos_date<=#{endDate, jdbcType = DATE}
			and status !='D'
			)

SELECT '小计' propertycode, ( SELECT NVL(SUM(NVL(CMAP.ASSETVALUE_B, 0)), 0) AS balance FROM CHB_MONTH_ASSET_POSITION CMAP LEFT JOIN CHB_ASSET_INFO INFO ON CMAP.ASSET_CODE = INFO.ASSET_CODE left join mst_customer_info_add mst on coalesce(info.chb_issuer_id,info.chb_manager_id,info.chb_financier_id)=mst.customer_id
WHERE CMAP.STARTDATE = #{startDate, jdbcType = DATE} and coalesce(info.chb_issuer_id,info.chb_manager_id,info.chb_financier_id) is not null AND mst.province IS NOT NULL and info.asset_type2 in ('1101','1110','1109','1111','1102','1112','1113','1114','1115','1116','1117')
and mst.PROVINCE in
#{province,jdbcType=VARCHAR}
and mst.PROVINCE not in
#{province,jdbcType=VARCHAR}
) AS sessionendNum, ( SELECT NVL(SUM(CMAP.ASSETVALUE_B), 0) FROM CHB_MONTH_ASSET_POSITION CMAP LEFT JOIN CHB_ASSET_INFO INFO ON CMAP.ASSET_CODE = INFO.ASSET_CODE left join mst_customer_info_add mst on coalesce(info.chb_issuer_id,info.chb_manager_id,info.chb_financier_id)=mst.customer_id
WHERE CMAP.STARTDATE = #{lastStartDate, jdbcType = DATE} and coalesce(info.chb_issuer_id,info.chb_manager_id,info.chb_financier_id) is not null AND mst.province IS NOT NULL and info.asset_type2 in ('1101','1110','1109','1111','1102','1112','1113','1114','1115','1116','1117')
and mst.PROVINCE in
#{province,jdbcType=VARCHAR}
and mst.PROVINCE not in
#{province,jdbcType=VARCHAR}
) AS lastSessionendNum, ( SELECT NVL(SUM(CMAP.ASSETVALUE_B), 0) FROM CHB_MONTH_ASSET_POSITION CMAP LEFT JOIN CHB_ASSET_INFO INFO ON CMAP.ASSET_CODE = INFO.ASSET_CODE left join mst_customer_info_add mst on coalesce(info.chb_issuer_id,info.chb_manager_id,info.chb_financier_id)=mst.customer_id
WHERE CMAP.STARTDATE = #{startDate, jdbcType = DATE} and coalesce(info.chb_issuer_id,info.chb_manager_id,info.chb_financier_id) is not null AND mst.province IS NOT NULL AND INFO.ASSET_TYPE2 IN ('2101', '2201', '2202', '2299','1201','1210','1202','1203','1204','1205','1206','1207','1208','1209','1299')
and mst.PROVINCE in
#{province,jdbcType=VARCHAR}
and mst.PROVINCE not in
#{province,jdbcType=VARCHAR}
) AS nonsStandardAmount, ( SELECT NVL(SUM(CMAP.ASSETVALUE_B), 0) FROM CHB_MONTH_ASSET_POSITION CMAP LEFT JOIN CHB_ASSET_INFO INFO ON CMAP.ASSET_CODE = INFO.ASSET_CODE left join mst_customer_info_add mst on coalesce(info.chb_issuer_id,info.chb_manager_id,info.chb_financier_id)=mst.customer_id
WHERE CMAP.STARTDATE = #{lastStartDate, jdbcType = DATE} and coalesce(info.chb_issuer_id,info.chb_manager_id,info.chb_financier_id) is not null AND mst.province IS NOT NULL AND INFO.ASSET_TYPE2 IN ('2101', '2201', '2202', '2299','1201','1210','1202','1203','1204','1205','1206','1207','1208','1209','1299')
and mst.PROVINCE in
#{province,jdbcType=VARCHAR}
and mst.PROVINCE not in
#{province,jdbcType=VARCHAR}
) AS lastNonsStandardAmount,
( SELECT NVL(SUM(CMAP.ASSETVALUE_B), 0) FROM CHB_MONTH_ASSET_POSITION CMAP LEFT JOIN CHB_ASSET_INFO INFO ON CMAP.ASSET_CODE = INFO.ASSET_CODE left join mst_customer_info_add mst on coalesce(info.chb_issuer_id,info.chb_manager_id,info.chb_financier_id)=mst.customer_id
WHERE CMAP.STARTDATE = #{startDate, jdbcType = DATE} and coalesce(info.chb_issuer_id,info.chb_manager_id,info.chb_financier_id) is not null AND mst.province IS NOT NULL AND INFO.ASSET_TYPE2 IN ('1106', '2401', '1303', '2403','2402','2499') and INFO.IS_GOVERN_FUND='01' and mst.IS_GOV='Y'
and mst.PROVINCE in
#{province,jdbcType=VARCHAR}
and mst.PROVINCE not in
#{province,jdbcType=VARCHAR}
) AS indInvestmentAmount, ( SELECT NVL(SUM(CMAP.ASSETVALUE_B), 0) FROM CHB_MONTH_ASSET_POSITION CMAP LEFT JOIN CHB_ASSET_INFO INFO ON CMAP.ASSET_CODE = INFO.ASSET_CODE left join mst_customer_info_add mst on coalesce(info.chb_issuer_id,info.chb_manager_id,info.chb_financier_id)=mst.customer_id
WHERE CMAP.STARTDATE = #{lastStartDate, jdbcType = DATE} and coalesce(info.chb_issuer_id,info.chb_manager_id,info.chb_financier_id) is not null AND mst.province IS NOT NULL AND INFO.ASSET_TYPE2 IN ('1106', '2401', '1303', '2403','2402','2499') and INFO.IS_GOVERN_FUND='01' and mst.IS_GOV='Y'
and mst.PROVINCE in
#{province,jdbcType=VARCHAR}
and mst.PROVINCE not in
#{province,jdbcType=VARCHAR}
) AS lastIndInvestmentAmount, ( SELECT NVL(SUM(CMAP.ASSETVALUE_B), 0) FROM CHB_MONTH_ASSET_POSITION CMAP LEFT JOIN CHB_ASSET_INFO INFO ON CMAP.ASSET_CODE = INFO.ASSET_CODE left join mst_customer_info_add mst on coalesce(info.chb_issuer_id,info.chb_manager_id,info.chb_financier_id)=mst.customer_id
WHERE CMAP.STARTDATE = #{startDate, jdbcType = DATE} and coalesce(info.chb_issuer_id,info.chb_manager_id,info.chb_financier_id) is not null AND INFO.ASSET_TYPE2 IN ('1002', '1003', '1004', '1005','1007','1301','1399','2617','2501','2502','1305')
and mst.PROVINCE in
#{province,jdbcType=VARCHAR}
and mst.PROVINCE not in
#{province,jdbcType=VARCHAR}
) AS otherAmount, ( SELECT NVL(SUM(CMAP.ASSETVALUE_B), 0) FROM CHB_MONTH_ASSET_POSITION CMAP LEFT JOIN CHB_ASSET_INFO INFO ON CMAP.ASSET_CODE = INFO.ASSET_CODE left join mst_customer_info_add mst on coalesce(info.chb_issuer_id,info.chb_manager_id,info.chb_financier_id)=mst.customer_id
WHERE CMAP.STARTDATE = #{lastStartDate, jdbcType = DATE} and coalesce(info.chb_issuer_id,info.chb_manager_id,info.chb_financier_id) is not null AND INFO.ASSET_TYPE2 IN ('1002', '1003', '1004', '1005','1007','1301','1399','2617','2501','2502','1305')
and mst.PROVINCE in
#{province,jdbcType=VARCHAR}
and mst.PROVINCE not in
#{province,jdbcType=VARCHAR}
) AS lastOtherAmount FROM DUAL

